code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find solid 3x3 marker squares by their color and bounding box.
    seen = set()
    centers = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            ys = [y for y,x in cells]; xs = [x for y,x in cells]
            y0,y1,x0,x1 = min(ys),max(ys),min(xs),max(xs)
            if y1-y0 == 2 and x1-x0 == 2 and len(cells) == 9 and all(grid[y][x] == color for y in range(y0,y1+1) for x in range(x0,x1+1)):
                centers.append((color, y0+1, x0+1))
    out = [row[:] for row in grid]
    claims = {}
    for color, cr, cc in centers:
        for x in range(w): claims.setdefault((cr,x), set()).add(color)
        for y in range(h): claims.setdefault((y,cc), set()).add(color)
    for (r,c), colors in claims.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
'''
